<script setup lang="ts">
import type { Project, ValueRef } from '../lib/model'
import { dataPoints } from '../lib/resources'
import { inputWidgetKinds } from '../lib/widgets'
const props = defineProps<{ modelValue: ValueRef; project: Project; literalType?: string }>()
const emit = defineEmits<{ 'update:modelValue': [value: ValueRef] }>()
function isInputWidget(widget: {kind:string}) { return inputWidgetKinds.includes(widget.kind) }
function changeSource(event: Event) {
  const source = (event.target as HTMLSelectElement).value as ValueRef['source']
  emit('update:modelValue', source === 'literal' ? {source,value:''} : source === 'message' || source === 'context' || source === 'runtime' ? {source,path:source==='message'?'payload':source==='runtime'?'state':'deviceKey'} : source === 'property' ? {source,key:'',property:'value'} : source === 'backend' ? {source,key:props.project.backends?.[0]?.id??'',path:''} : {source,key:''})
}
function literal(value: string) { let parsed: unknown = value; try { parsed = JSON.parse(value) } catch { /* Plain strings are valid literals. */ } emit('update:modelValue', { source: 'literal', value: parsed }) }
</script>
<template><div class="value-editor">
  <select :value="modelValue.source" aria-label="值来源" @change="changeSource"><option value="literal">常量</option><option value="message">消息字段</option><option value="variable">项目变量</option><option value="input">控件输入</option><option value="point">设备数据点</option><option value="property">控件属性</option><option value="backend">后端状态</option><option value="context">窗口上下文</option><option value="runtime">运行状态</option></select>
  <input v-if="modelValue.source === 'literal'" :value="typeof modelValue.value === 'object' ? JSON.stringify(modelValue.value) : String(modelValue.value ?? '')" placeholder="输入值或 JSON" @change="literal(($event.target as HTMLInputElement).value)" />
  <input v-else-if="modelValue.source === 'message' || modelValue.source === 'context'" :value="modelValue.path" :placeholder="modelValue.source==='context'?'deviceKey':'payload.temperature'" @change="emit('update:modelValue', { source: modelValue.source, path: ($event.target as HTMLInputElement).value })" />
  <template v-else-if="modelValue.source === 'variable'"><select :value="modelValue.key" @change="emit('update:modelValue', { ...modelValue, key: ($event.target as HTMLSelectElement).value })"><option value="">选择变量</option><option v-for="variable in project.variables" :key="variable.id" :value="variable.id">{{ variable.name }}</option></select><input :value="modelValue.path??''" placeholder="留空读取整个变量，如 byDevice.$deviceKey.state" aria-label="变量字段路径" @change="emit('update:modelValue',{...modelValue,path:($event.target as HTMLInputElement).value})"/></template>
  <select v-else-if="modelValue.source==='runtime'" :value="modelValue.path" aria-label="运行状态字段" @change="emit('update:modelValue',{source:'runtime',path:($event.target as HTMLSelectElement).value})"><option value="state">运行状态</option><option value="error">错误信息</option><option value="locale">当前语言</option></select>
  <select v-else-if="modelValue.source === 'input'" :value="modelValue.key" @change="emit('update:modelValue', { source: 'input', key: ($event.target as HTMLSelectElement).value })"><option value="">选择输入控件</option><template v-for="page in project.pages" :key="page.id"><option v-for="widget in page.widgets.filter(isInputWidget)" :key="widget.id" :value="widget.id">{{ page.name }} / {{ widget.name }}</option></template></select>
  <template v-else-if="modelValue.source==='property'"><select :value="modelValue.key" @change="emit('update:modelValue',{source:'property',key:($event.target as HTMLSelectElement).value,property:modelValue.property})"><option value="">选择控件</option><template v-for="page in project.pages" :key="page.id"><option v-for="widget in page.widgets" :key="widget.id" :value="widget.id">{{page.name}} / {{widget.name}}</option></template></select><input :value="modelValue.property" placeholder="属性名，如 value" @change="emit('update:modelValue',{...modelValue,property:($event.target as HTMLInputElement).value})"/></template>
  <template v-else-if="modelValue.source==='backend'"><select :value="modelValue.key" @change="emit('update:modelValue',{...modelValue,key:($event.target as HTMLSelectElement).value})"><option value="">选择后端</option><option v-for="backend in project.backends??[]" :key="backend.id" :value="backend.id">{{backend.name}}</option></select><input :value="modelValue.path" placeholder="devices.$deviceKey.state" aria-label="后端状态路径" @change="emit('update:modelValue',{...modelValue,path:($event.target as HTMLInputElement).value})"/></template>
  <template v-else-if="modelValue.source==='point'"><input :value="modelValue.key" list="hmi-data-point-options" placeholder="sensor.temperature" @change="emit('update:modelValue', { source: 'point', key: ($event.target as HTMLSelectElement).value })" /><datalist id="hmi-data-point-options"><option v-for="point in dataPoints(project)" :key="point.key" :value="point.key">{{ point.label }}</option></datalist></template>
</div></template>
